import numpy as np

# Test input
test_input = np.array([
    [0, 0, 3],
    [3, 3, 0],
    [0, 3, 0]
])

# Rule: kernel = NOT(input_positions)
input_binary = (test_input != 0).astype(int)
kernel = np.logical_not(input_binary).astype(int)
print("Test kernel:")
print(kernel)

# Build output
output = np.zeros((9, 9))
for i in range(3):
    for j in range(3):
        if test_input[i, j] != 0:
            # Place the kernel scaled by input value
            val = int(test_input[i, j])
            for kr in range(3):
                for kc in range(3):
                    if kernel[kr, kc] == 1:
                        output[3*i + kr, 3*j + kc] = val

print("\nPredicted output:")
for row in output:
    print(list(row))

